参考实现（JavaScript，快慢指针 / Floyd 判圈）：
function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}
时间复杂度 O(n)，额外空间复杂度 O(1)。

